const out = [];
for (const it of $input.all()) {
  for (const m of (it.json.messages || [])) out.push({ json: { id: m.id } });
}
return out;

const H = (m, n) => {
  const hs = (m.payload && m.payload.headers) || [];
  const h = hs.find((x) => String(x.name).toLowerCase() === n);
  return h ? String(h.value) : null;
};
const addrs = (v) => {
  if (!v) return null;
  const f = String(v).match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g);
  return f ? Array.from(new Set(f.map((x) => x.toLowerCase()))).join(',') : null;
};
const rows = [];
for (const it of $input.all()) {
  const m = it.json;
  if (!m || !m.id) continue;
  const from = addrs(H(m, 'from'));
  rows.push({
    gmail_id: m.id,
    thread_id: m.threadId || null,
    mailbox: from,
    from_email: from,
    to_emails: addrs(H(m, 'to')),
    cc_emails: addrs(H(m, 'cc')),
    subject: H(m, 'subject'),
    snippet: m.snippet || null,
    sent_at: m.internalDate ? new Date(Number(m.internalDate)).toISOString() : null,
  });
}
const out = [];
for (let i = 0; i < rows.length; i += 400) out.push({ json: { chunk: rows.slice(i, i + 400) } });
return out;

