// Three days of overlap, deliberately. A missed run, a late Gmail sync or a
// clock skew would otherwise leave a permanent hole in the history, and
// gmail_id is the primary key so re-reading a message costs nothing.
return [{ json: { body: { q: '(in:sent OR in:inbox) newer_than:3d -category:promotions -category:social' } } }];

// One day during working hours: enough overlap to survive a skipped run,
// small enough to re-read cheaply every hour. The 22:30 run still sweeps
// three days, so a longer outage is caught by that rather than by making
// every hourly pass expensive.
return [{ json: { body: { q: '(in:sent OR in:inbox) newer_than:1d -category:promotions -category:social' } } }];

